import json
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    maj=cnt.most_common(1)[0][0]
    sep=[r for r in range(H) if Counter(g[r]).most_common(1)[0][0]!=maj]
    sepC=[c for c in range(W) if Counter([r[c] for r in g]).most_common(1)[0][0]!=maj]
    res=[]
    for a,b in zip(sep,sep[1:]):
        vals=[]
        for x,y in zip(sepC,sepC[1:]):
            cs=[g[a][x],g[a][y],g[b][x],g[b][y]]
            if cs.count(cs[0])==4 and cs[0]!=maj: vals.append(cs[0])
        if not vals or vals[-1]!=vals[0]:
            res.append([]) if False else None
        if len(set(vals))==1 and vals: res.append(vals)
        elif vals: res.append(vals[:1]) # keep first? 
        else: res.append([maj])
    return res
